import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

triu_matmul_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_pipeline.h>

#define TILE_M 128
#define TILE_M_PAD (TILE_M + 4)
#define TILE_N 128
#define TILE_K 16
#define THREAD_TILE 8
#define BLOCK_DIM 16
#define WARP_SIZE 32
#define WARP_ROWS 4
#define WARP_COLS 2
#define WM (TILE_M / WARP_ROWS)
#define WN (TILE_N / WARP_COLS)
#define LANE_ROWS (WM / THREAD_TILE)
#define LANE_COLS (WN / THREAD_TILE)
__device__ __forceinline__ void loadATile(const float* __restrict__ A,
                                           float (*As)[TILE_M_PAD],
                                           int blockRow, int k0, int N, int tid) {
    #pragma unroll
    for (int half = 0; half < TILE_M / 64; half++) {
        int rowLocal = (tid >> 2) + half * 64;   // tid / 4, offset by half
        int vecIdx = tid & 3;                    // tid % 4
        int c0 = vecIdx * 4;
        int gRow = blockRow + rowLocal;
        int gCol0 = k0 + c0;
        if (gRow < N && gCol0 + 3 < N) {
            float4 v = *reinterpret_cast<const float4*>(&A[gRow * N + gCol0]);
            As[c0 + 0][rowLocal] = v.x;
            As[c0 + 1][rowLocal] = v.y;
            As[c0 + 2][rowLocal] = v.z;
            As[c0 + 3][rowLocal] = v.w;
        } else {
            #pragma unroll
            for (int c = 0; c < 4; c++) {
                int gCol = gCol0 + c;
                As[c0 + c][rowLocal] = (gRow < N && gCol < N) ? A[gRow * N + gCol] : 0.0f;
            }
        }
    }
}
__device__ __forceinline__ void loadBTile(const float* __restrict__ B,
                                           float (*Bs)[TILE_N],
                                           int blockCol, int k0, int N, int tid) {
    int rowLocal = tid >> 4;          // tid / 16
    int vecIdx = tid & 15;            // tid % 16
    #pragma unroll
    for (int half = 0; half < TILE_N / 64; half++) {
        int c0 = vecIdx * 4 + half * 64;
        int gRow = k0 + rowLocal;
        int gCol0 = blockCol + c0;
        if (gRow < N && gCol0 + 3 < N) {
#if __CUDA_ARCH__ >= 800
            __pipeline_memcpy_async(&Bs[rowLocal][c0], &B[gRow * N + gCol0], sizeof(float4));
#else
            float4 v = *reinterpret_cast<const float4*>(&B[gRow * N + gCol0]);
            Bs[rowLocal][c0 + 0] = v.x;
            Bs[rowLocal][c0 + 1] = v.y;
            Bs[rowLocal][c0 + 2] = v.z;
            Bs[rowLocal][c0 + 3] = v.w;
#endif
        } else {
            #pragma unroll
            for (int c = 0; c < 4; c++) {
                int gCol = gCol0 + c;
                Bs[rowLocal][c0 + c] = (gRow < N && gCol < N) ? B[gRow * N + gCol] : 0.0f;
            }
        }
    }
}
__global__ void triu_matmul_kernel(const float* __restrict__ A,
                                    const float* __restrict__ B,
                                    float* __restrict__ C,
                                    int N) {
    __shared__ float As[2][TILE_K][TILE_M_PAD];
    __shared__ float Bs[2][TILE_K][TILE_N];
    int blockRow = blockIdx.y * TILE_M;
    int blockCol = blockIdx.x * TILE_N;
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int tid = ty * BLOCK_DIM + tx;
    int warpId = tid / WARP_SIZE;
    int laneId = tid % WARP_SIZE;
    int warpRow = warpId / WARP_COLS;
    int warpCol = warpId % WARP_COLS;
    int laneRow = laneId / LANE_COLS;
    int laneCol = laneId % LANE_COLS;
    int rowBase = warpRow * WM + laneRow * THREAD_TILE;
    int colBase = warpCol * WN + laneCol * THREAD_TILE;
    float sum[THREAD_TILE][THREAD_TILE];
    #pragma unroll
    for (int i = 0; i < THREAD_TILE; i++) {
        #pragma unroll
        for (int j = 0; j < THREAD_TILE; j++) {
            sum[i][j] = 0.0f;
        }
    }
    // Only compute if this block could contain non-zero upper-triangular contributions
    if (blockCol + TILE_N - 1 >= blockRow) {
        int numTiles = (N + TILE_K - 1) / TILE_K;
        // The skip/break conditions from the original loop are monotonic in t,
        // so the set of tiles actually processed is a contiguous range [tStart, tEnd).
        int tStart = blockRow / TILE_K;
        int tEndTile = (blockCol + TILE_N - 1) / TILE_K;
        int tEnd = tEndTile + 1;
        if (tStart < 0) tStart = 0;
        if (tEnd > numTiles) tEnd = numTiles;
        int nTiles = tEnd - tStart;
        if (nTiles > 0) {
            // Prologue: prefetch first tile into buffer 0
            loadATile(A, As[0], blockRow, tStart * TILE_K, N, tid);
            loadBTile(B, Bs[0], blockCol, tStart * TILE_K, N, tid);
#if __CUDA_ARCH__ >= 800
            __pipeline_commit();
            __pipeline_wait_prior(0);
#endif
            __syncthreads();
            for (int idx = 0; idx < nTiles; idx++) {
                int cur = idx & 1;
                int nextIdx = idx + 1;
                // Prefetch next tile into the other buffer while computing on 'cur'
                if (nextIdx < nTiles) {
                    int nxt = nextIdx & 1;
                    int k0next = (tStart + nextIdx) * TILE_K;
                    loadATile(A, As[nxt], blockRow, k0next, N, tid);
                    loadBTile(B, Bs[nxt], blockCol, k0next, N, tid);
                    #if __CUDA_ARCH__ >= 800
                    __pipeline_commit();
                    #endif
                }
                float aFrag[2][THREAD_TILE];
                float bFrag[2][THREAD_TILE];
                {
                    float4 aVec0 = *reinterpret_cast<const float4*>(&As[cur][0][rowBase]);
                    float4 aVec1 = *reinterpret_cast<const float4*>(&As[cur][0][rowBase + 4]);
                    aFrag[0][0] = aVec0.x;
                    aFrag[0][1] = aVec0.y;
                    aFrag[0][2] = aVec0.z;
                    aFrag[0][3] = aVec0.w;
                    aFrag[0][4] = aVec1.x;
                    aFrag[0][5] = aVec1.y;
                    aFrag[0][6] = aVec1.z;
                    aFrag[0][7] = aVec1.w;
                    float4 bVec0 = *reinterpret_cast<const float4*>(&Bs[cur][0][colBase]);
                    float4 bVec1 = *reinterpret_cast<const float4*>(&Bs[cur][0][colBase + 4]);
                    bFrag[0][0] = bVec0.x;
                    bFrag[0][1] = bVec0.y;
                    bFrag[0][2] = bVec0.z;
                    bFrag[0][3] = bVec0.w;
                    bFrag[0][4] = bVec1.x;
                    bFrag[0][5] = bVec1.y;
                    bFrag[0][6] = bVec1.z;
                    bFrag[0][7] = bVec1.w;
                }
                #pragma unroll
                for (int k = 0; k < TILE_K; k++) {
                    int curBuf = k & 1;
                    int nextBuf = curBuf ^ 1;
                    if (k + 1 < TILE_K) {
                        float4 aVec0 = *reinterpret_cast<const float4*>(&As[cur][k + 1][rowBase]);
                        float4 aVec1 = *reinterpret_cast<const float4*>(&As[cur][k + 1][rowBase + 4]);
                        aFrag[nextBuf][0] = aVec0.x;
                        aFrag[nextBuf][1] = aVec0.y;
                        aFrag[nextBuf][2] = aVec0.z;
                        aFrag[nextBuf][3] = aVec0.w;
                        aFrag[nextBuf][4] = aVec1.x;
                        aFrag[nextBuf][5] = aVec1.y;
                        aFrag[nextBuf][6] = aVec1.z;
                        aFrag[nextBuf][7] = aVec1.w;
                        float4 bVec0 = *reinterpret_cast<const float4*>(&Bs[cur][k + 1][colBase]);
                        float4 bVec1 = *reinterpret_cast<const float4*>(&Bs[cur][k + 1][colBase + 4]);
                        bFrag[nextBuf][0] = bVec0.x;
                        bFrag[nextBuf][1] = bVec0.y;
                        bFrag[nextBuf][2] = bVec0.z;
                        bFrag[nextBuf][3] = bVec0.w;
                        bFrag[nextBuf][4] = bVec1.x;
                        bFrag[nextBuf][5] = bVec1.y;
                        bFrag[nextBuf][6] = bVec1.z;
                        bFrag[nextBuf][7] = bVec1.w;
                    }
                    #pragma unroll
                    for (int i = 0; i < THREAD_TILE; i++) {
                        #pragma unroll
                        for (int j = 0; j < THREAD_TILE; j++) {
                            sum[i][j] += aFrag[curBuf][i] * bFrag[curBuf][j];
                        }
                    }
                }
                #if __CUDA_ARCH__ >= 800
                __pipeline_wait_prior(0);
                #endif
                __syncthreads();
            }
        }
    }
    #pragma unroll
    for (int i = 0; i < THREAD_TILE; i++) {
        int row = blockRow + rowBase + i;
        if (row >= N) continue;
        #pragma unroll
        for (int j = 0; j < THREAD_TILE; j++) {
            int col = blockCol + colBase + j;
            if (col < N) {
                C[row * N + col] = (row <= col) ? sum[i][j] : 0.0f;
            }
        }
    }
}
torch::Tensor triu_matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dtype() == torch::kFloat32, "A must be float32");
    TORCH_CHECK(B.dtype() == torch::kFloat32, "B must be float32");
    A = A.contiguous();
    B = B.contiguous();
    int N = A.size(0);
    auto C = torch::empty({N, N}, A.options());
    dim3 block(BLOCK_DIM, BLOCK_DIM);
    dim3 grid((N + TILE_N - 1) / TILE_N, (N + TILE_M - 1) / TILE_M);
    triu_matmul_kernel<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        N
    );
    return C;
}
"""

triu_matmul_cpp_source = r"""
torch::Tensor triu_matmul_cuda(torch::Tensor A, torch::Tensor B);
"""

triu_matmul_module = load_inline(
    name="triu_matmul_module",
    cpp_sources=triu_matmul_cpp_source,
    cuda_sources=triu_matmul_source,
    functions=["triu_matmul_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs matrix multiplication (C = A * B) for upper
    triangular matrices using a custom fused CUDA kernel that skips
    computation for tiles guaranteed to be zero due to the triangular
    structure, and masks the lower triangle of the output.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.triu_matmul = triu_matmul_module

    def forward(self, A, B):
        return self.triu_matmul.triu_matmul_cuda(A, B)


N = 4096

def get_inputs():
    A = torch.triu(torch.rand(N, N)).cuda()
    B = torch.triu(torch.rand(N, N)).cuda()
    return [A, B]

def get_init_inputs():
    return []

